def run(api):
    s = api.inspect("state")
    if s["acknowledged"]:
        if s["leased"]:
            api.apply("release_lease")
        return
    if not s["leased"]:
        s = api.apply("claim")
    if not s["committed"]:
        if not s["applied"]:
            if s["transactional"]:
                if not s["transaction"]:
                    s = api.apply("begin")
                s = api.apply("apply_transactional")
            else:
                s = api.apply("apply_direct")
        if not s["outbox"]:
            s = api.apply("stage_outbox")
        if s["transactional"]:
            s = api.apply("commit_transaction")
        else:
            s = api.apply("persist_direct")
    if not s["delivered"]:
        if s["deduplicating_sink"]:
            s = api.apply("deliver_idempotently")
        else:
            if not s["receipt_checked"]:
                s = api.apply("check_delivery_receipt")
            s = api.apply("deliver_once")
    if not s["acknowledged"]:
        s = api.apply("acknowledge")
    if s["leased"]:
        api.apply("release_lease")
